/* From Uiverse.io by MuhammadHasann - Tags: button */
.__UIV_SCOPE__ button {
  position: relative;
  padding: 13px 35px;
  background: transparent;
  font-size: 17px;
  font-weight: 900;
  border: none;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ button::after {
  content: "Read More";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 155px;
  height: 47px;
  background-color: #ffffff;
  font-size: 17px;
  font-weight: 900;
  line-height: 47px;
  color: #181818;
  border: 2px solid #181818;
  border-radius: 50px;
  transition: all .3s ease-in-out;
  z-index: 2;
}

.__UIV_SCOPE__ button:hover::after {
  width: 165px;
  height: 50px;
  font-size: 18px;
  line-height: 50px;
}

.__UIV_SCOPE__ button:focus::after {
  content: "Read less";
  top: 200%;
  width: 155px;
  height: 47px;
  font-size: 17px;
  line-height: 47px;
  z-index: -2;
  pointer-events: none;
}

.__UIV_SCOPE__ .icon {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, 0);
  width: 20px;
  height: auto;
  z-index: -3;
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ button:focus .icon {
  top: -250%;
  width: 75px;
  height: auto;
}

.__UIV_SCOPE__ .fil0 {
  fill: #333333
}

.__UIV_SCOPE__ .fil2 {
  fill: #222222
}

.__UIV_SCOPE__ .fil1 {
  fill: #181818
}

.__UIV_SCOPE__ .fil3 {
  fill: #181818
}
